package com.tripmateai.service.impl; import com.tripmateai.dto.request.budget.*; import com.tripmateai.dto.response.budget.*; import com.tripmateai.entity.*; import com.tripmateai.exception.*; import com.tripmateai.mapper.BudgetMapper; import com.tripmateai.repository.*; import com.tripmateai.security.UserPrincipal; import com.tripmateai.service.BudgetService; import lombok.RequiredArgsConstructor; import org.springframework.security.core.context.SecurityContextHolder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.*;
@Service @RequiredArgsConstructor @Transactional public class BudgetServiceImpl implements BudgetService {private final BudgetRepository budgets;private final TripRepository trips;private final ExpenseRepository expenses;private User user(){var p=SecurityContextHolder.getContext().getAuthentication().getPrincipal();if(!(p instanceof UserPrincipal u))throw new UnauthorizedException("Authentication required");return u.user();} private Trip trip(Long id){return trips.findByIdAndUser(id,user()).orElseThrow(()->trips.existsById(id)?new UnauthorizedException("You do not have access to this trip"):new ResourceNotFoundException("Trip not found"));} private Budget budget(Long tripId){return budgets.findByTrip(trip(tripId)).orElseThrow(()->new ResourceNotFoundException("Budget not found"));} public BudgetResponse create(Long id,BudgetRequest r){if(!id.equals(r.tripId()))throw new BadRequestException("Trip ID must match path");var t=trip(id);if(budgets.existsByTrip(t))throw new BadRequestException("A budget already exists for this trip");var b=new Budget();b.setTrip(t);b.setTotalBudget(r.totalBudget());b.setAllocatedAmount(r.allocatedAmount()==null?BigDecimal.ZERO:r.allocatedAmount());b.setCurrency(r.currency()==null||r.currency().isBlank()?"INR":r.currency().toUpperCase());return BudgetMapper.toResponse(budgets.save(b));} @Transactional(readOnly=true) public BudgetResponse get(Long id){return BudgetMapper.toResponse(budget(id));} public BudgetResponse update(Long id,UpdateBudgetRequest r){var b=budget(id);b.setTotalBudget(r.totalBudget());b.setAllocatedAmount(r.allocatedAmount()==null?BigDecimal.ZERO:r.allocatedAmount());if(r.currency()!=null)b.setCurrency(r.currency());return BudgetMapper.toResponse(budgets.save(b));} public void delete(Long id){budgets.delete(budget(id));} @Transactional(readOnly=true) public BudgetSummaryResponse summary(Long id){var b=budget(id);var total=expenses.findByTrip(b.getTrip()).stream().map(Expense::getAmount).reduce(BigDecimal.ZERO,BigDecimal::add);return new BudgetSummaryResponse(b.getTotalBudget(),total,b.getTotalBudget().subtract(total));}}
